  tecnicas: [
    { id: "colores", nombre: "Código de colores", para: "Que todo el grupo lea el mapa igual.", como: "Pósits amarillos para pasos, rosas para problemas, azules para tiempos y verdes para ideas. Una leyenda con un pósit de cada color en un lateral de la pared.", frase: "Amarillo, pasos; rosa, problemas; azul, tiempos; verde, ideas." },
    { id: "parking", nombre: "Parking de ideas", para: "Que ninguna idea se pierda y el grupo no se desvíe del objetivo.", como: "Una hoja visible (o la zona de pósits verdes). Al cerrar, se repasa y se decide cuándo tratar cada idea; se registran en la ficha.", frase: "Es una buena idea; la aparcamos aquí y no se pierde." },
    { id: "ronda", nombre: "Ronda", para: "Que hablen todos, no solo los de siempre.", como: "Pregunta concreta y turnos de un minuto por persona. Se puede pasar.", frase: "Por turnos: ¿cuál es el principal problema que veis en el alta? Una frase cada uno." },
    { id: "silencio", nombre: "Escritura en silencio", para: "Que la primera opinión, o la del jefe, no condicione al resto.", como: "3–5 minutos escribiendo en pósits, una idea por pósit. Después se leen y se pegan.", frase: "Durante 4 minutos, escribid en silencio dónde creéis que se pierde más tiempo." },
    { id: "124", nombre: "1-2-4-todos", para: "Muchas ideas en un grupo grande.", como: "1 minuto solo, 2 en parejas, 4 en grupos de cuatro y puesta en común.", frase: "Primero un minuto cada uno, en silencio…" },
    { id: "semaforo", nombre: "Semáforo", para: "Validar rápido un borrador.", como: "Verde, ámbar o rojo por afirmación. Se debate sobre todo lo ámbar y lo rojo.", frase: "Afirmación 3: … ¿Verde, ámbar o rojo?" },
    { id: "puntos", nombre: "Votación por puntos", para: "Priorizar entre muchas opciones.", como: "Tres puntos por persona para repartir. Se cuentan.", frase: "Tenéis tres puntos cada uno. Ponedlos donde creáis que hay más impacto." },
    { id: "punyo", nombre: "Puño a cinco", para: "Comprobar si una decisión tiene apoyo real.", como: "Cada uno muestra de 0 (bloqueo) a 5 (apoyo total). Con 0–2, se pregunta qué haría falta.", frase: "Del 0 al 5, ¿os representa este problema?" },
    { id: "pared", nombre: "Mapa en la pared", para: "Construir entre todos el recorrido real.", como: "Papel continuo, leyenda de colores, un pósit amarillo por paso; tiempos en azul y problemas en rosa debajo.", frase: "¿Y después qué pasa? ¿Quién lo hace?" },
    { id: "ultima", nombre: "«La última vez que…»", para: "Bajar de lo general a lo real.", como: "Cuando alguien dice «normalmente», pide el último caso paso a paso.", frase: "Cuéntanos la última vez que pasó (sin datos del paciente)." },
    { id: "gemba", nombre: "Ir a ver (gemba)", para: "Ver el proceso donde ocurre.", como: "Recorrer el lugar de trabajo con quien lo hace: observar primero, preguntar después, no corregir.", frase: "¿Me enseñas cómo lo haces?" },
    { id: "tiempo", nombre: "Tiempo visible", para: "Respetar los bloques.", como: "Alguien controla el tiempo y avisa 2 minutos antes del final de cada bloque.", frase: "Nos quedan dos minutos para este bloque." },
    { id: "cierre", nombre: "Cierre con responsables", para: "Que la sesión produzca acción.", como: "Últimos 10 minutos: cada acuerdo en voz alta con quién y para cuándo, apuntado en la hoja de compromisos a la vista de todos; repaso del parking de ideas. Una foto de la hoja es la base del acta.", frase: "¿Quién se encarga? ¿Para cuándo?" }
  ],

